 states=row['states'];ego=states['ego'];reference=row['subject_stopping_reference'];front=max(v[0] for v in ego['body_vertices_m']);inventory=row['governing_native_inventory']
 return {'ego_speed':ego['speed_mps'],'participant_native_state':states,'native_actor_inventory':inventory,'intersection_occupancy':row['occupancy'],'participant_interaction_history':{'states':states,'actual_controls':{k:s['applied_control'] for k,s in states.items()},'requested_controls':row['control_requests'],'engineering_phase':row['engineering_phase'],'contacts':row['contacts']},'stopping_motion_history':{'position_m':ego['position_m'],'velocity_mps':ego['velocity_mps'],'speed_mps':ego['speed_mps'],'actual_controls':ego['applied_control'],'body_vertices_m':ego['body_vertices_m'],'actual_reference':reference,'front_to_reference_gap_m':reference['upstream_x_m']-front,'measurement_resolution':'Original20Hz and Native floating point; no legal epsilon or span'},'driver_viewpoint_visibility':{'Native_potential_vehicle_place_measurements':row['driver_place_sight_distance'],'actual_user_body_rays':event['original_observations']['relations'],'original_cameras':row['camera_original_frames'],'model_point_local_m':[0,0,1.5],'anatomical_eye_or_human_perception_observed':False},'original_camera_graph_body_Core_joins':{'native_frame':row['frame'],'original_time_s':row['time_s'],'expected_Core_t_ms':round(row['time_s']*1000),'actual_actor_ids':[s['actor_id'] for s in states.values()],'original_camera_frames':row['camera_original_frames'],'original_entrance_packet':event['original_observations']['stop2572_entrance_control_native'],'independent_Core_join_pending':True},'counterpart_center_station':states['initial_crossing']['position_m'][1],'counterpart_phase':row['occupancy']['initial_crossing']['crossing_front_approach_distance_m']}

def action(rows,mode):
 gaps=[r['subject_stopping_reference']['upstream_x_m']-max(v[0] for v in r['states']['ego']['body_vertices_m']) for r in rows];cross=next((i for i in range(1,len(rows)) if gaps[i]<0<=gaps[i-1]),None)
 if cross is None:return {'confirmed':False,'reason':'No actual applicable reference passage'}
 peak=max(range(cross+1),key=lambda i:rows[i]['states']['ego']['speed_mps']);zero=[{'index':i,'time_s':rows[i]['time_s'],'velocity_mps':rows[i]['states']['ego']['velocity_mps'],'position_m':rows[i]['states']['ego']['position_m'],'front_to_reference_gap_m':gaps[i],'actual_controls':rows[i]['states']['ego']['applied_control']} for i in range(peak,cross+1) if rows[i]['states']['ego']['speed_mps']==0 and all(v==0 for v in rows[i]['states']['ego']['velocity_mps'])]
 actual_forward=[rows[i]['states']['ego']['position_m'][0]-rows[i-1]['states']['ego']['position_m'][0] for i in range(peak+1,cross+1)];confirmed=any(z['front_to_reference_gap_m']>0 for z in zero) if mode=='stop' else not zero and bool(actual_forward) and all(v>0 for v in actual_forward) and all(rows[i]['states']['ego']['speed_mps']>0 for i in range(peak,cross+1))
 return {'confirmed':confirmed,'mode':mode,'peak_index':peak,'leading_reference_crossing_index':cross,'leading_reference_crossing_bracket_s':[rows[cross-1]['time_s'],rows[cross]['time_s']],'exact_zero_raw_velocity_samples':zero,'minimum_raw_speed_peak_to_reference_mps':min(rows[i]['states']['ego']['speed_mps'] for i in range(peak,cross+1)),'minimum_positive_forward_step_m':min(actual_forward) if actual_forward else None,'sampling_interval_s':.05,'legal_standard_created':False}

def finish(out,cfg,rows,report,error):
 out=Path(out);roles={'ego','initial_crossing','further_crossing'};reference=json.loads((out/'measured-reference-event.json').read_text()) if (out/'measured-reference-event.json').exists() else None;matched=min(rows,key=lambda r:abs(r['time_s']-reference['time_s'])) if rows and reference else None
 clearance={role:next((r['time_s'] for r in rows if min(v[0] for v in r['states'][role]['body_vertices_m'])>7 if role=='ego'),None) if role=='ego' else next((r['time_s'] for r in rows if max(v[1] for v in r['states'][role]['body_vertices_m'])<-7),None) for role in roles}
 final=[r for r in rows if r['time_s']>cfg['duration_s']-3];stopping=action(rows,cfg['stop_mode']) if rows else {'confirmed':False};first_overlap=next((r['time_s'] for r in rows if r['occupancy']['ego']['body_overlap']),None)
 checks={'all_original_frames':len(rows)==cfg['maximum_frames'] and error is None,'all_actual_participant_identities':bool(rows) and all(set(r['states'])==roles and {s['actor_id'] for s in r['states'].values()}=={a['actor_id'] for a in r['native_actor_inventory'] if a['type_id'].startswith('vehicle.')} for r in rows),'no_contacts':not report['contacts'],'all_bodies_on_operating_pavement':bool(rows) and all(all(r['body_inside_pavement'].values()) for r in rows),'all_participant_crossings_clear':all(t is not None for t in clearance.values()),'final_observation_after_all_clear':bool(rows) and all(t is not None for t in clearance.values()) and rows[-1]['time_s']-max(clearance.values())>=3,'engineering_final_response_complete':len(final)>=59 and all(s['speed_mps']<.03 for r in final for s in r['states'].values()),'reference_event_observed':matched is not None,'actual_stop_or_roll_contrast':stopping['confirmed'],'subject_full_body_inside_observed':any(r['occupancy']['ego']['full_body_inside'] for r in rows),'no_premature_subject_overlap':first_overlap is not None and clearance['initial_crossing'] is not None and first_overlap>clearance['initial_crossing'],'new_entrance_graph_capture_every_frame':bool(rows) and all(r['governing_native_inventory'].get('actual_vehicle_waypoints') for r in rows)}
 if cfg['initial_target_y_m']==0:checks['occupied_counterpart_at_reference']=matched is not None and matched['occupancy']['initial_crossing']['full_body_inside']
 else:checks['positive_approach_at_reference']=matched is not None and matched['occupancy']['initial_crossing']['crossing_front_approach_distance_m']>0
 target_checks=[{'target':name,'requested':True,'measured':{'observed':bool(value)},'matched':bool(value),'method':'Original Native identities/full bodies/control/geometry/reference and complete response histories. Engineering completion is separate from statutory judgments.','tolerance':'No missing declared samples; no legal cessation epsilon/span or caution/hazard threshold','physical_cause_confirmed':bool(rows),'cause_evidence':['native-motion.jsonl','native_control_inventory.jsonl','native_incoming_lane_topology.json','video_frames.jsonl','native-reference-context.json']} for name,value in checks.items()]
 realized={}
 for axis in cfg['case'].get('sweep_measurements',[]):
  observable=axis['observable']
  if observable in ['counterpart_center_station','counterpart_phase'] and matched:
   actual=matched['states']['initial_crossing']['position_m'][1] if observable=='counterpart_center_station' else matched['occupancy']['initial_crossing']['crossing_front_approach_distance_m'];window=[matched['time_s'],matched['time_s']]
  elif observable=='ego_speed' and rows:
   crossing=[r for r in rows if r['engineering_phase']=='subject_progress'];actual=max((r['states']['ego']['speed_mps'] for r in crossing),default=None);window=[crossing[0]['time_s'],crossing[-1]['time_s']] if crossing else None
  else:continue
  realized[observable]={'value':actual,'unit':axis['unit'],**axis['measurement'],'sample_window_s':window,'reference':'channels/'+observable+'.jsonl'}
 complete=all(checks.values());result={'status':'draft','cell_id':cfg['cell_id'],'actor':cfg['actor'],'case_id':cfg['case_id'],'input_revision':cfg['input_revision'],'primary_video_reference':'overview.mkv','setup_confirmed':bool(rows),'behavior_attempted':any(r['states']['ego']['speed_mps']>0 for r in rows),'maneuver_completed':complete,'termination_reason':'complete_original_history' if complete else 'incomplete_physical_or_observation_contract','physical_failure_flags':{'collision':bool(report['contacts']),'roadway_departure':not checks['all_bodies_on_operating_pavement']},'target_checks':target_checks,'measured_values':{'frames':len(rows),'duration_s':rows[-1]['time_s'] if rows else 0,'whole_body_clearance_times_s':clearance,'reference_time_s':None if matched is None else matched['time_s'],'actual_stopping_measurement':stopping},'trace_reference':'trace.jsonl','video_references':['overview.mkv','approach.mkv','reference_corner.mkv','driver_reference.mkv'],'video_frame_map_reference':'video_frames.jsonl','recording_description':cfg['recording_description'],'recording_evidence':[{'name':c['name'],'unit':c['unit'],'reference':'channels/'+c['name']+'.jsonl'} for c in cfg['recording_description']['channels']]+[{'name':c['name'],'unit':c['unit'],'reference':'context.json'} for c in cfg['recording_description']['context_inputs']],'realized_observables':realized,'recording_complete':len(rows)==cfg['maximum_frames'] and error is None,'requested_variable_assignments':{k:v for k,v in cfg['variable_assignments'].items() if v['kind'] in ['world_setup','controller']},'authored_context':cfg['authored_test_context'],'error':error,'restoration':{'restored':report['restored']},'limitations':cfg['recording_description']['limitations'],'judgments_unresolved':['proceed cautiously','immediate hazard','yielding to vehicles not so obligated'],'video_Core_pair_accepted':False}
 with (out/'result.json').open('x') as f:json.dump(result,f,indent=2,allow_nan=False);f.write('\n')
 return complete

"""Owned-scene teardown barriers and fresh-client baseline restoration, CARLA0.9.15."""
import hashlib,json,time

def restore(carla,client,world,owned,previous,weather,prior_path,prior_xml,host,port,directory):
 def event(stage,**values):
  with (directory/'cleanup-progress-v3.jsonl').open('a') as f:f.write(json.dumps(dict(at=time.time(),stage=stage,**values),allow_nan=False)+'\n')
 ids={a.id for a in owned};event('stop_all_owned_sensor_callbacks',owned_actor_ids=sorted(ids))
 for a in owned:
  if a.type_id.startswith('sensor.') and a.is_listening:a.stop()
 event('batch_destroy_owned_actors')
 order=sorted(owned,key=lambda a:not a.type_id.startswith('sensor.'))
 fresh_destroy=carla.Client(host,port,2);fresh_destroy.set_timeout(30)
 responses=fresh_destroy.apply_batch_sync([carla.command.DestroyActor(a.id) for a in order],False)
 if any(r.has_error() for r in responses):raise RuntimeError('Owned actor batch destruction failed: '+str([r.error for r in responses if r.has_error()]))
 for _ in range(2):world.tick()
 remaining=[{'id':a.id,'type':a.type_id} for a in world.get_actors() if a.id in ids or a.type_id.startswith(('vehicle.','walker.','sensor.'))]
 if remaining:raise RuntimeError('Native dynamic actors remain after teardown barrier: '+str(remaining))
 event('native_actor_absence_confirmed',remaining=remaining)
 world.apply_settings(previous)
 first=world.wait_for_tick(30);second=world.wait_for_tick(30)
 if not second.frame>first.frame:raise RuntimeError('No native asynchronous frame advance before map restoration')
 event('native_async_frames_confirmed',frames=[first.frame,second.frame])
 fresh=carla.Client(host,port,2);fresh.set_timeout(180)
 event('load_prior_native_map_with_settings_preserved',native_map_path=prior_path)
 restored=fresh.load_world(prior_path,False)
 restored.set_weather(weather);restored.apply_settings(previous)
 actual=hashlib.sha256(restored.get_map().to_opendrive().encode()).hexdigest();expected=hashlib.sha256(prior_xml.encode()).hexdigest()
 if actual!=expected:raise RuntimeError('Prior native map hash mismatch')
 for observed,target in [(restored.get_settings(),previous),(restored.get_weather(),weather)]:
  for k in dir(target):
   if k.startswith('_'):continue
   v=getattr(target,k)
   if not isinstance(v,(bool,int,float,type(None))):continue
   got=getattr(observed,k)
   if isinstance(v,(int,float)) and not isinstance(v,bool):
    if abs(got-v)>1e-5:raise RuntimeError('Prior native settings/weather mismatch: '+k)
   elif got!=v:raise RuntimeError('Prior native settings/weather mismatch: '+k)
 event('prior_native_baseline_verified',map_sha256=actual)
 return {'restored':True,'previous_map_name':restored.get_map().name,'previous_map_sha256':actual,'settings_and_weather_verified':True,'restoration_method':'sensor stop, ordered batch destruction, native absence and asynchronous-frame barriers; fresh bounded client native-map reload preserving settings','cleanup_implementation':'cleanup_v3.py'}

